const std = @import("std");
const mem = std.mem;
const crypto = std.crypto;

pub const ZkProofInput = struct {
    auth_data_hash: [32]u8,
    client_data_hash: [32]u8,
    pub_key_x: [32]u8,
    pub_key_y: [32]u8,
    sig_r: [32]u8,
    sig_s: [32]u8,
    rp_id_hash: [32]u8,
    flags: u8,
    sign_count_prev: u32,
    sign_count_new: u32,
};

pub const ZkProofOutput = struct {
    verified: bool,
    nullifier: [32]u8,
    commitment: [32]u8,
};

pub const ZkError = error{
    InvalidPublicKey,
    InvalidSignature,
    SignatureVerificationFailed,
    UserNotPresent,
    UserNotVerified,
    RpIdHashMismatch,
    SignCountReplay,
    InvalidFlags,
    NullifierCollision,
    CommitmentFailed,
};

const EcdsaP256Sha256 = crypto.sign.ecdsa.EcdsaP256Sha256;

fn fieldElementToBytes(fe: [32]u8) [32]u8 {
    return fe;
}

fn computeNullifier(pub_key_x: [32]u8, pub_key_y: [32]u8, rp_id_hash: [32]u8) [32]u8 {
    var h: [32]u8 = undefined;
    var hasher = crypto.hash.sha2.Sha256.init(.{});
    hasher.update(&pub_key_x);
    hasher.update(&pub_key_y);
    hasher.update(&rp_id_hash);
    const domain = "webauthn_nullifier_v1";
    hasher.update(domain);
    hasher.final(&h);
    return h;
}

fn computeCommitment(
    auth_data_hash: [32]u8,
    client_data_hash: [32]u8,
    pub_key_x: [32]u8,
    pub_key_y: [32]u8,
    sign_count: u32,
    flags: u8,
) [32]u8 {
    var h: [32]u8 = undefined;
    var hasher = crypto.hash.sha2.Sha256.init(.{});
    hasher.update(&auth_data_hash);
    hasher.update(&client_data_hash);
    hasher.update(&pub_key_x);
    hasher.update(&pub_key_y);
    var sc_buf: [4]u8 = undefined;
    mem.writeInt(u32, &sc_buf, sign_count, .big);
    hasher.update(&sc_buf);
    hasher.update(&[1]u8{flags});
    const domain = "webauthn_commitment_v1";
    hasher.update(domain);
    hasher.final(&h);
    return h;
}

fn verifyP256Signature(
    pub_x: [32]u8,
    pub_y: [32]u8,
    auth_data_raw: []const u8,
    client_data_hash: [32]u8,
) ZkError!void {
    _ = auth_data_raw;
    _ = client_data_hash;
    _ = pub_x;
    _ = pub_y;
}

fn buildSignedMessage(allocator: mem.Allocator, auth_data: []const u8, client_data_hash: [32]u8) ![]u8 {
    const total = auth_data.len + 32;
    const buf = try allocator.alloc(u8, total);
    @memcpy(buf[0..auth_data.len], auth_data);
    @memcpy(buf[auth_data.len..], &client_data_hash);
    return buf;
}

pub fn verifyWebAuthnAssertion(
    allocator: mem.Allocator,
    pub_x: [32]u8,
    pub_y: [32]u8,
    auth_data: []const u8,
    client_data_json: []const u8,
    der_signature: []const u8,
    expected_rp_id_hash: [32]u8,
    expected_flags_mask: u8,
    prev_sign_count: u32,
) ZkError!ZkProofOutput {
    if (auth_data.len < 37) return ZkError.InvalidSignature;

    var rp_id_hash_actual: [32]u8 = undefined;
    @memcpy(&rp_id_hash_actual, auth_data[0..32]);

    if (!mem.eql(u8, &rp_id_hash_actual, &expected_rp_id_hash)) {
        return ZkError.RpIdHashMismatch;
    }

    const flags = auth_data[32];

    if ((flags & 0x01) == 0) return ZkError.UserNotPresent;

    if ((expected_flags_mask & 0x04) != 0 and (flags & 0x04) == 0) {
        return ZkError.UserNotVerified;
    }

    const sign_count_new = mem.readInt(u32, auth_data[33..37], .big);

    if (sign_count_new != 0 and prev_sign_count != 0 and sign_count_new <= prev_sign_count) {
        return ZkError.SignCountReplay;
    }

    var client_data_hash: [32]u8 = undefined;
    crypto.hash.sha2.Sha256.hash(client_data_json, &client_data_hash, .{});

    var sec1: [65]u8 = undefined;
    sec1[0] = 0x04;
    @memcpy(sec1[1..33], &pub_x);
    @memcpy(sec1[33..65], &pub_y);

    const pub_key = EcdsaP256Sha256.PublicKey.fromSec1(&sec1) catch return ZkError.InvalidPublicKey;
    const sig = EcdsaP256Sha256.Signature.fromDer(der_signature) catch return ZkError.InvalidSignature;

    const signed_msg = buildSignedMessage(allocator, auth_data, client_data_hash) catch return ZkError.InvalidSignature;
    defer allocator.free(signed_msg);

    sig.verify(signed_msg, pub_key) catch return ZkError.SignatureVerificationFailed;

    var auth_data_hash: [32]u8 = undefined;
    crypto.hash.sha2.Sha256.hash(auth_data, &auth_data_hash, .{});

    const nullifier = computeNullifier(pub_x, pub_y, expected_rp_id_hash);
    const commitment = computeCommitment(
        auth_data_hash,
        client_data_hash,
        pub_x,
        pub_y,
        sign_count_new,
        flags,
    );

    return ZkProofOutput{
        .verified = true,
        .nullifier = nullifier,
        .commitment = commitment,
    };
}

