pub fn derSignatureToRS(der: []const u8) ZkError![64]u8 {
    if (der.len < 8) return ZkError.InvalidSignature;
    if (der[0] != 0x30) return ZkError.InvalidSignature;
    var pos: usize = 2;
    if (der[pos] != 0x02) return ZkError.InvalidSignature;
    pos += 1;
    const r_len: usize = der[pos];
    pos += 1;
    const r_start = pos;
    const r_end = pos + r_len;
    if (r_end > der.len) return ZkError.InvalidSignature;
    pos = r_end;
    if (pos >= der.len or der[pos] != 0x02) return ZkError.InvalidSignature;
    pos += 1;
    if (pos >= der.len) return ZkError.InvalidSignature;
    const s_len: usize = der[pos];
    pos += 1;
    const s_start = pos;
    const s_end = pos + s_len;
    if (s_end > der.len) return ZkError.InvalidSignature;

    var result: [64]u8 = std.mem.zeroes([64]u8);

    const r_bytes = der[r_start..r_end];
    const s_bytes = der[s_start..s_end];

    const r_offset: usize = if (r_len > 32 and r_bytes[0] == 0x00) r_len - 32 else 0;
    const s_offset: usize = if (s_len > 32 and s_bytes[0] == 0x00) s_len - 32 else 0;

    const r_copy_len = @min(r_len - r_offset, 32);
    const s_copy_len = @min(s_len - s_offset, 32);

    const r_dest_start = 32 - r_copy_len;
    const s_dest_start = 64 - s_copy_len;

    @memcpy(result[r_dest_start .. r_dest_start + r_copy_len], r_bytes[r_offset .. r_offset + r_copy_len]);
    @memcpy(result[s_dest_start .. s_dest_start + s_copy_len], s_bytes[s_offset .. s_offset + s_copy_len]);

    return result;
}

fn bytesToBigIntDecimal(allocator: mem.Allocator, bytes: []const u8) ![]u8 {
    var result = try allocator.dupe(u8, "0");
    errdefer allocator.free(result);

    for (bytes) |byte| {
        var carry: u64 = byte;
        var new_digits = std.ArrayList(u8).init(allocator);
        defer new_digits.deinit();

        var i: usize = result.len;
        while (i > 0) {
            i -= 1;
            const digit_val = @as(u64, result[i] - '0');
            const prod = digit_val * 256 + carry;
            carry = prod / 10;
            const remainder = prod % 10;
            try new_digits.append(@as(u8, @intCast(remainder)) + '0');
        }
        while (carry > 0) {
            try new_digits.append(@as(u8, @intCast(carry % 10)) + '0');
            carry /= 10;
        }

        const new_len = new_digits.items.len;
        var reversed = try allocator.alloc(u8, new_len);
        defer allocator.free(reversed);
        for (new_digits.items, 0..) |d, idx| {
            reversed[new_len - 1 - idx] = d;
        }

        allocator.free(result);
        result = try allocator.dupe(u8, reversed);
    }

    return result;
}

pub fn generateCircomInput(
    allocator: mem.Allocator,
    input: ZkProofInput,
) ![]u8 {
    const rs = try derSignatureToRS(&([_]u8{0x30} ++ [_]u8{0x00}));
    _ = rs;

    var sig_r_dec = try bytesToBigIntDecimal(allocator, &input.sig_r);
    defer allocator.free(sig_r_dec);
    var sig_s_dec = try bytesToBigIntDecimal(allocator, &input.sig_s);
    defer allocator.free(sig_s_dec);
    var pub_x_dec = try bytesToBigIntDecimal(allocator, &input.pub_key_x);
    defer allocator.free(pub_x_dec);
    var pub_y_dec = try bytesToBigIntDecimal(allocator, &input.pub_key_y);
    defer allocator.free(pub_y_dec);

    var msg_concat: [64]u8 = undefined;
    @memcpy(msg_concat[0..32], &input.auth_data_hash);
    @memcpy(msg_concat[32..64], &input.client_data_hash);
    var msg_hash: [32]u8 = undefined;
    crypto.hash.sha2.Sha256.hash(&msg_concat, &msg_hash, .{});

    var msg_dec = try bytesToBigIntDecimal(allocator, &msg_hash);
    defer allocator.free(msg_dec);

    var out = std.ArrayList(u8).init(allocator);
    const w = out.writer();

    try w.writeAll("{\n");
    try w.print("  \"r\": \"{s}\",\n", .{sig_r_dec});
    try w.print("  \"s\": \"{s}\",\n", .{sig_s_dec});
    try w.print("  \"pubkey_x\": \"{s}\",\n", .{pub_x_dec});
    try w.print("  \"pubkey_y\": \"{s}\",\n", .{pub_y_dec});
    try w.print("  \"msghash\": \"{s}\",\n", .{msg_dec});

    try w.writeAll("  \"auth_data_hash_bits\": [");
    for (input.auth_data_hash, 0..) |byte, i| {
        var b: u8 = byte;
        var bit_idx: u3 = 7;
        while (true) {
            const bit = (b >> bit_idx) & 1;
            if (i > 0 or bit_idx < 7) try w.writeByte(',');
            try w.print("{d}", .{bit});
            if (bit_idx == 0) break;
            bit_idx -= 1;
        }
    }
    try w.writeAll("],\n");

    try w.writeAll("  \"client_data_hash_bits\": [");
    for (input.client_data_hash, 0..) |byte, i| {
        var b: u8 = byte;
        var bit_idx: u3 = 7;
        while (true) {
            const bit = (b >> bit_idx) & 1;
            if (i > 0 or bit_idx < 7) try w.writeByte(',');
            try w.print("{d}", .{bit});
            if (bit_idx == 0) break;
            bit_idx -= 1;
        }
    }
    try w.writeAll("],\n");

    try w.writeAll("  \"rp_id_hash_bits\": [");
    for (input.rp_id_hash, 0..) |byte, i| {
        var b: u8 = byte;
        var bit_idx: u3 = 7;
        while (true) {
            const bit = (b >> bit_idx) & 1;
            if (i > 0 or bit_idx < 7) try w.writeByte(',');
            try w.print("{d}", .{bit});
            if (bit_idx == 0) break;
            bit_idx -= 1;
        }
    }
    try w.writeAll("],\n");

    try w.print("  \"flags\": {d},\n", .{input.flags});
    try w.print("  \"sign_count_prev\": {d},\n", .{input.sign_count_prev});
    try w.print("  \"sign_count_new\": {d}\n", .{input.sign_count_new});
    try w.writeAll("}\n");

    return out.toOwnedSlice();
}

pub fn runFullVerificationTest(allocator: mem.Allocator) !void {
    const stdout = std.io.getStdOut().writer();

    var key_pair = EcdsaP256Sha256.KeyPair.generate() catch {
        try stdout.writeAll("FAIL: key generation\n");
        return;
    };

    const pub_key = key_pair.public_key;
    const sec1_bytes = pub_key.toUncompressedSec1();

    var pub_x: [32]u8 = undefined;
    var pub_y: [32]u8 = undefined;
    @memcpy(&pub_x, sec1_bytes[1..33]);
    @memcpy(&pub_y, sec1_bytes[33..65]);

    const rp_id = "localhost";
    var rp_id_hash: [32]u8 = undefined;
    crypto.hash.sha2.Sha256.hash(rp_id, &rp_id_hash, .{});

    var auth_data: [37]u8 = std.mem.zeroes([37]u8);
    @memcpy(auth_data[0..32], &rp_id_hash);
    auth_data[32] = 0x05;
    mem.writeInt(u32, auth_data[33..37], 1, .big);

    const client_data_json =
        \\{"type":"webauthn.get","challenge":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","origin":""}
    ;

    var client_data_hash: [32]u8 = undefined;
    crypto.hash.sha2.Sha256.hash(client_data_json, &client_data_hash, .{});

    const signed_msg = try mem.concat(allocator, u8, &.{ &auth_data, &client_data_hash });
    defer allocator.free(signed_msg);

    const sig = key_pair.sign(signed_msg, null) catch {
        try stdout.writeAll("FAIL: signing\n");
        return;
    };

    const der_sig = sig.toDer();

    const result = verifyWebAuthnAssertion(
        allocator,
        pub_x,
        pub_y,
        &auth_data,
        client_data_json,
        &der_sig,
        rp_id_hash,
        0x04,
        0,
    ) catch |err| {
        try stdout.print("FAIL: verification error: {}\n", .{err});
        return;
    };

    if (!result.verified) {
        try stdout.writeAll("FAIL: not verified\n");
        return;
    }

    try stdout.writeAll("PASS: WebAuthn ZK assertion verified\n");

    try stdout.writeAll("nullifier: ");
    for (result.nullifier) |b| try stdout.print("{x:0>2}", .{b});
    try stdout.writeByte('\n');
    try stdout.writeAll("commitment: ");
    for (result.commitment) |b| try stdout.print("{x:0>2}", .{b});
    try stdout.writeByte('\n');

    const auth_data_hash = blk: {
        var h: [32]u8 = undefined;
        crypto.hash.sha2.Sha256.hash(&auth_data, &h, .{});
        break :blk h;
    };

    var rs: [64]u8 = std.mem.zeroes([64]u8);
    const der_bytes = sig.toDer();
    rs = try derSignatureToRS(&der_bytes);

    const witness_input = ZkProofInput{
        .auth_data_hash = auth_data_hash,
        .client_data_hash = client_data_hash,
        .pub_key_x = pub_x,
        .pub_key_y = pub_y,
        .sig_r = rs[0..32].*,
        .sig_s = rs[32..64].*,
        .rp_id_hash = rp_id_hash,
        .flags = 0x05,
        .sign_count_prev = 0,
        .sign_count_new = 1,
    };

    const circom_json = try generateCircomInput(allocator, witness_input);
    defer allocator.free(circom_json);

    const circom_file = try std.fs.cwd().createFile("webauthn_input.json", .{});
    defer circom_file.close();
    try circom_file.writeAll(circom_json);

    try stdout.writeAll("PASS: circom input written to webauthn_input.json\n");

    const tampered_auth_data = blk: {
        var copy = auth_data;
        copy[0] ^= 0xFF;
        break :blk copy;
    };

    const should_fail = verifyWebAuthnAssertion(
        allocator,
        pub_x,
        pub_y,
        &tampered_auth_data,
        client_data_json,
        &der_sig,
        rp_id_hash,
        0x04,
        0,
    );

    if (should_fail) |_| {
        try stdout.writeAll("FAIL: tampered auth_data was not rejected\n");
    } else |_| {
        try stdout.writeAll("PASS: tampered auth_data correctly rejected\n");
    }

    var wrong_key_pair = EcdsaP256Sha256.KeyPair.generate() catch {
        try stdout.writeAll("SKIP: wrong key generation failed\n");
        return;
    };
    const wrong_pub = wrong_key_pair.public_key;
    const wrong_sec1 = wrong_pub.toUncompressedSec1();
    var wrong_x: [32]u8 = undefined;
    var wrong_y: [32]u8 = undefined;
    @memcpy(&wrong_x, wrong_sec1[1..33]);
    @memcpy(&wrong_y, wrong_sec1[33..65]);

    const wrong_key_result = verifyWebAuthnAssertion(
        allocator,
        wrong_x,
        wrong_y,
        &auth_data,
        client_data_json,
        &der_sig,
        rp_id_hash,
        0x04,
        0,
    );

    if (wrong_key_result) |_| {
        try stdout.writeAll("FAIL: wrong key was not rejected\n");
    } else |_| {
        try stdout.writeAll("PASS: wrong key correctly rejected\n");
    }

    var no_uv_auth_data = auth_data;
    no_uv_auth_data[32] = 0x01;

    const no_uv_result = verifyWebAuthnAssertion(
        allocator,
        pub_x,
        pub_y,
        &no_uv_auth_data,
        client_data_json,
        &der_sig,
        rp_id_hash,
        0x04,
        0,
    );

    if (no_uv_result) |_| {
        try stdout.writeAll("FAIL: missing UV flag was not rejected when required\n");
    } else |_| {
        try stdout.writeAll("PASS: missing UV flag correctly rejected when required\n");
    }

    var replay_auth_data = auth_data;
    mem.writeInt(u32, replay_auth_data[33..37], 1, .big);

    const replay_result = verifyWebAuthnAssertion(
        allocator,
        pub_x,
        pub_y,
        &replay_auth_data,
        client_data_json,
        &der_sig,
        rp_id_hash,
        0x04,
        5,
    );

    if (replay_result) |_| {
        try stdout.writeAll("FAIL: sign count replay was not rejected\n");
    } else |err| {
        if (err == ZkError.SignCountReplay) {
            try stdout.writeAll("PASS: sign count replay correctly rejected\n");
        } else {
            try stdout.print("PASS: rejected with error: {}\n", .{err});
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    try runFullVerificationTest(allocator);
}
