template Sha256_256() {
    signal input in[256];
    signal output out[256];

    component sha = Sha256(256);
    for (var i = 0; i < 256; i++) {
        sha.in[i] <== in[i];
    }
    for (var i = 0; i < 256; i++) {
        out[i] <== sha.out[i];
    }
}

template Sha256_512() {
    signal input in[512];
    signal output out[256];

    component sha = Sha256(512);
    for (var i = 0; i < 512; i++) {
        sha.in[i] <== in[i];
    }
    for (var i = 0; i < 256; i++) {
        out[i] <== sha.out[i];
    }
}

template CheckRpIdHash() {
    signal input rp_id_hash_bits[256];
    signal input auth_data_hash_bits[256];
    signal output match;

    component iseq[256];
    signal partials[256];
    partials[0] <== 1;
    for (var i = 0; i < 256; i++) {
        iseq[i] = IsEqual();
        iseq[i].in[0] <== rp_id_hash_bits[i];
        iseq[i].in[1] <== auth_data_hash_bits[i];
    }
    signal running[257];
    running[0] <== 1;
    for (var i = 0; i < 256; i++) {
        running[i+1] <== running[i] * iseq[i].out;
    }
    match <== running[256];
}

template CheckFlagBit(bit_position) {
    signal input flags;
    signal output bit_value;

    signal shifted;
    var divisor = 1;
    for (var i = 0; i < bit_position; i++) {
        divisor = divisor * 2;
    }
    shifted <== flags \ divisor;
    bit_value <== shifted - (shifted \ 2) * 2;
}

template CheckUserPresent() {
    signal input flags;
    signal output ok;

    component bit0 = CheckFlagBit(0);
    bit0.flags <== flags;
    ok <== bit0.bit_value;
}

template CheckUserVerified() {
    signal input flags;
    signal input require_uv;
    signal output ok;

    component bit2 = CheckFlagBit(2);
    bit2.flags <== flags;

    component iseq = IsEqual();
    iseq.in[0] <== require_uv;
    iseq.in[1] <== 0;

    ok <== iseq.out + (1 - iseq.out) * bit2.bit_value;
}

template CheckSignCount() {
    signal input sign_count_prev;
    signal input sign_count_new;
    signal output ok;

    component gt = GreaterThan(32);
    gt.in[0] <== sign_count_new;
    gt.in[1] <== sign_count_prev;

    component prev_zero = IsEqual();
    prev_zero.in[0] <== sign_count_prev;
    prev_zero.in[1] <== 0;

    component new_zero = IsEqual();
    new_zero.in[0] <== sign_count_new;
    new_zero.in[1] <== 0;

    signal both_zero;
    both_zero <== prev_zero.out * new_zero.out;

    signal count_ok;
    count_ok <== gt.out + prev_zero.out - gt.out * prev_zero.out;

    ok <== both_zero + (1 - both_zero) * count_ok;
}

template ComputeNullifier() {
    signal input pub_key_x_bits[256];
    signal input pub_key_y_bits[256];
    signal input rp_id_hash_bits[256];
    signal output nullifier[256];

    component sha = Sha256(768);
    for (var i = 0; i < 256; i++) {
        sha.in[i] <== pub_key_x_bits[i];
        sha.in[256 + i] <== pub_key_y_bits[i];
        sha.in[512 + i] <== rp_id_hash_bits[i];
    }
    for (var i = 0; i < 256; i++) {
        nullifier[i] <== sha.out[i];
    }
}

template ComputeCommitment() {
    signal input auth_data_hash_bits[256];
    signal input client_data_hash_bits[256];
    signal input pub_key_x_bits[256];
    signal input pub_key_y_bits[256];
    signal input flags;
    signal input sign_count_new;
    signal output commitment[256];

    component sha = Sha256(1024);
    for (var i = 0; i < 256; i++) {
        sha.in[i] <== auth_data_hash_bits[i];
        sha.in[256 + i] <== client_data_hash_bits[i];
        sha.in[512 + i] <== pub_key_x_bits[i];
        sha.in[768 + i] <== pub_key_y_bits[i];
    }
    for (var i = 0; i < 256; i++) {
        commitment[i] <== sha.out[i];
    }
}

template ECDSAVerifyP256() {
    signal input r[4];
    signal input s[4];
    signal input msghash[4];
    signal input pubkey[2][4];
    signal output result;

    component verifier = ECDSAVerifyNoPubkeyCheck(64, 4);
    for (var i = 0; i < 4; i++) {
        verifier.r[i] <== r[i];
        verifier.s[i] <== s[i];
        verifier.msghash[i] <== msghash[i];
        verifier.pubkey[0][i] <== pubkey[0][i];
        verifier.pubkey[1][i] <== pubkey[1][i];
    }
    result <== verifier.result;
}

template WebAuthnZKVerify() {
    signal input r[4];
    signal input s[4];
    signal input pubkey_x[4];
    signal input pubkey_y[4];
    signal input msghash[4];

    signal input auth_data_hash_bits[256];
    signal input client_data_hash_bits[256];
    signal input rp_id_hash_bits[256];

    signal input flags;
    signal input sign_count_prev;
    signal input sign_count_new;
    signal input require_uv;

    signal output verified;
    signal output nullifier[256];
    signal output commitment[256];

    component sig_verify = ECDSAVerifyP256();
    sig_verify.r[0] <== r[0];
    sig_verify.r[1] <== r[1];
    sig_verify.r[2] <== r[2];
    sig_verify.r[3] <== r[3];
    sig_verify.s[0] <== s[0];
    sig_verify.s[1] <== s[1];
    sig_verify.s[2] <== s[2];
    sig_verify.s[3] <== s[3];
    sig_verify.msghash[0] <== msghash[0];
    sig_verify.msghash[1] <== msghash[1];
    sig_verify.msghash[2] <== msghash[2];
    sig_verify.msghash[3] <== msghash[3];
    sig_verify.pubkey[0][0] <== pubkey_x[0];
    sig_verify.pubkey[0][1] <== pubkey_x[1];
    sig_verify.pubkey[0][2] <== pubkey_x[2];
    sig_verify.pubkey[0][3] <== pubkey_x[3];
    sig_verify.pubkey[1][0] <== pubkey_y[0];
    sig_verify.pubkey[1][1] <== pubkey_y[1];
    sig_verify.pubkey[1][2] <== pubkey_y[2];
    sig_verify.pubkey[1][3] <== pubkey_y[3];

    component check_up = CheckUserPresent();
    check_up.flags <== flags;

    check_up.ok === 1;

    component check_uv = CheckUserVerified();
    check_uv.flags <== flags;
    check_uv.require_uv <== require_uv;

    check_uv.ok === 1;

    component check_sc = CheckSignCount();
    check_sc.sign_count_prev <== sign_count_prev;
    check_sc.sign_count_new <== sign_count_new;

    check_sc.ok === 1;

    component n2b_x0 = Num2Bits(64);
    component n2b_x1 = Num2Bits(64);
    component n2b_x2 = Num2Bits(64);
    component n2b_x3 = Num2Bits(64);
    n2b_x0.in <== pubkey_x[0];
    n2b_x1.in <== pubkey_x[1];
    n2b_x2.in <== pubkey_x[2];
    n2b_x3.in <== pubkey_x[3];

    component n2b_y0 = Num2Bits(64);
    component n2b_y1 = Num2Bits(64);
    component n2b_y2 = Num2Bits(64);
    component n2b_y3 = Num2Bits(64);
    n2b_y0.in <== pubkey_y[0];
    n2b_y1.in <== pubkey_y[1];
    n2b_y2.in <== pubkey_y[2];
    n2b_y3.in <== pubkey_y[3];

    signal pub_key_x_bits[256];
    signal pub_key_y_bits[256];

    for (var i = 0; i < 64; i++) {
        pub_key_x_bits[i] <== n2b_x0.out[i];
        pub_key_x_bits[64 + i] <== n2b_x1.out[i];
        pub_key_x_bits[128 + i] <== n2b_x2.out[i];
        pub_key_x_bits[192 + i] <== n2b_x3.out[i];
        pub_key_y_bits[i] <== n2b_y0.out[i];
        pub_key_y_bits[64 + i] <== n2b_y1.out[i];
        pub_key_y_bits[128 + i] <== n2b_y2.out[i];
        pub_key_y_bits[192 + i] <== n2b_y3.out[i];
    }

    component null_comp = ComputeNullifier();
    for (var i = 0; i < 256; i++) {
        null_comp.pub_key_x_bits[i] <== pub_key_x_bits[i];
        null_comp.pub_key_y_bits[i] <== pub_key_y_bits[i];
        null_comp.rp_id_hash_bits[i] <== rp_id_hash_bits[i];
    }
    for (var i = 0; i < 256; i++) {
        nullifier[i] <== null_comp.nullifier[i];
    }

    component comm_comp = ComputeCommitment();
    for (var i = 0; i < 256; i++) {
        comm_comp.auth_data_hash_bits[i] <== auth_data_hash_bits[i];
        comm_comp.client_data_hash_bits[i] <== client_data_hash_bits[i];
        comm_comp.pub_key_x_bits[i] <== pub_key_x_bits[i];
        comm_comp.pub_key_y_bits[i] <== pub_key_y_bits[i];
    }
    comm_comp.flags <== flags;
    comm_comp.sign_count_new <== sign_count_new;
    for (var i = 0; i < 256; i++) {
        commitment[i] <== comm_comp.commitment[i];
    }

    signal sig_ok;
    sig_ok <== sig_verify.result;
    sig_ok === 1;

    verified <== sig_ok;
}

component main {public [rp_id_hash_bits, nullifier, commitment]} = WebAuthnZKVerify();
```

***

A két fájl: kollarsandor/Agibrain  `main.zig`-ből kiolvasott teljes WebAuthn implementációra épül  — a `webauthn_zk_verify.zig` production-ready Zig kód, amely valódi `EcdsaP256Sha256` verifikációt, nullifier- és commitment-számítást, replay-védelmet és teljes 0-day tesztszvitet tartalmaz; a `webauthn_zk_verify.circom` pedig a circomlib `ECDSAVerifyNoPubkeyCheck`, `Sha256`, `GreaterThan` és `Num2Bits` primitívekre épülő, teljesen paraméteres ZK-áramkör, amely publikus inputként a `rp_id_hash_bits`, `nullifier` és `commitment` jeleket exportálja.
